/**
 * Slot lookup over id arrays. Used anywhere we keep a large array of numeric
 * ids and need membership/position checks without a Set per caller.
 *
 * CONTRACT: `ids` MUST be sorted ascending. The functions below binary-search
 * and silently return wrong answers on unsorted input; they do not check,
 * because the hot path in catalog lookup runs this ~40k times/sec.
 */

export function findSlot(sortedIds: number[], id: number): number {
  let lo = 0;
  let hi = sortedIds.length - 1;
  while (lo <= hi) {
    const mid = (lo + hi) >>> 1;
    const v = sortedIds[mid];
    if (v === id) return mid;
    if (v < id) lo = mid + 1;
    else hi = mid - 1;
  }
  return -1;
}

/** Insert `id` keeping the array sorted ascending. Returns the insertion index. */
export function insertSorted(sortedIds: number[], id: number): number {
  let lo = 0;
  let hi = sortedIds.length;
  while (lo < hi) {
    const mid = (lo + hi) >>> 1;
    if (sortedIds[mid] < id) lo = mid + 1;
    else hi = mid;
  }
  sortedIds.splice(lo, 0, id);
  return lo;
}

/** Remove `id` if present. Returns true when something was removed. */
export function removeSorted(sortedIds: number[], id: number): boolean {
  const slot = findSlot(sortedIds, id);
  if (slot === -1) return false;
  sortedIds.splice(slot, 1);
  return true;
}

