import { findSlot, insertSorted } from "../lib/slots.js";

/**
 * In-memory SKU catalog. SKU ids come from the central id service and are
 * NOT monotonic per warehouse node: each node draws from an interleaved
 * block allocator, so a node can see id 90411 before id 12007. That is why
 * every array here is maintained through insertSorted rather than push.
 */
export interface Sku {
  id: number;
  name: string;
  stock: number;
}

export class Catalog {
  private readonly skus = new Map<number, Sku>();
  private readonly allSkuIds: number[] = [];

  add(sku: Sku): void {
    if (this.skus.has(sku.id)) throw new Error("duplicate sku " + sku.id);
    this.skus.set(sku.id, sku);
    insertSorted(this.allSkuIds, sku.id);
  }

  has(id: number): boolean {
    return findSlot(this.allSkuIds, id) !== -1;
  }

  get(id: number): Sku | undefined {
    return this.skus.get(id);
  }

  adjustStock(id: number, delta: number): number {
    const sku = this.skus.get(id);
    if (sku === undefined) throw new Error("unknown sku " + id);
    sku.stock += delta;
    if (sku.stock < 0) throw new Error("negative stock for sku " + id);
    return sku.stock;
  }

  /** Ids in ascending order; safe to hand to findSlot. */
  ids(): readonly number[] {
    return this.allSkuIds;
  }

  size(): number {
    return this.allSkuIds.length;
  }
}

