import { findSlot } from "../lib/slots.js";
import type { Catalog } from "./catalog.js";

/**
 * Stock reservations with a TTL. A reservation holds stock for a checkout
 * until it is confirmed, cancelled, or expires. `recentIds` tracks
 * reservation ids in recency order for the ops dashboard's "recent activity"
 * panel: new reservations are appended, and touch() moves a renewed
 * reservation to the end so the panel shows the latest activity last.
 */
export interface Reservation {
  id: number;
  skuId: number;
  qty: number;
  expiresAt: number;
}

export class Reservations {
  private readonly byId = new Map<number, Reservation>();
  private readonly recentIds: number[] = [];

  constructor(private readonly catalog: Catalog) {}

  reserve(r: Reservation): void {
    if (this.byId.has(r.id)) throw new Error("duplicate reservation " + r.id);
    this.catalog.adjustStock(r.skuId, -r.qty);
    this.byId.set(r.id, r);
    this.recentIds.push(r.id);
  }

  /** Renew a reservation's TTL and surface it in the dashboard panel. */
  touch(id: number, now: number, ttlMs: number): void {
    const r = this.byId.get(id);
    if (r === undefined) return;
    r.expiresAt = now + ttlMs;
    const at = this.recentIds.indexOf(id);
    if (at !== -1) this.recentIds.splice(at, 1);
    this.recentIds.push(id);
  }

  confirm(id: number): void {
    const r = this.byId.get(id);
    if (r === undefined) throw new Error("unknown reservation " + id);
    this.byId.delete(id);
    const slot = findSlot(this.recentIds, id);
    if (slot !== -1) this.recentIds.splice(slot, 1);
  }

  /** Called by the sweeper every 30s. Returns stock to the catalog. */
  releaseExpired(now: number): number {
    let released = 0;
    for (const r of [...this.byId.values()]) {
      if (r.expiresAt > now) continue;
      this.catalog.adjustStock(r.skuId, r.qty);
      this.byId.delete(r.id);
      const slot = findSlot(this.recentIds, r.id);
      if (slot !== -1) this.recentIds.splice(slot, 1);
      released += 1;
    }
    return released;
  }

  recent(limit: number): number[] {
    return this.recentIds.slice(-limit);
  }

  active(): number {
    return this.byId.size;
  }

  /** Dashboard invariant: every id in the panel is a live reservation. */
  panelConsistent(): boolean {
    return this.recentIds.every((id) => this.byId.has(id));
  }
}

