import type { Reservations } from "./reservations.js";

/**
 * Background sweeper. Runs releaseExpired on an interval and reports to the
 * ops dashboard. Shipped in the previous release; this release only adds the
 * consistency probe at the bottom.
 */
export interface SweeperStats {
  sweeps: number;
  released: number;
  lastSweepAt: number;
  panelConsistent: boolean;
}

export function startSweeper(
  reservations: Reservations,
  intervalMs: number,
  onStats: (stats: SweeperStats) => void,
): () => void {
  const stats: SweeperStats = { sweeps: 0, released: 0, lastSweepAt: 0, panelConsistent: true };
  const timer = setInterval(() => {
    const now = Date.now();
    stats.released += reservations.releaseExpired(now);
    stats.sweeps += 1;
    stats.lastSweepAt = now;
    // Probe added this release: alerts ops when the dashboard panel drifts
    // from the live reservation set. Fires PANEL_DRIFT on the dashboard.
    stats.panelConsistent = reservations.panelConsistent();
    onStats({ ...stats });
  }, intervalMs);
  return () => clearInterval(timer);
}

