import type { Catalog } from "./catalog.js";
import type { Reservation, Reservations } from "./reservations.js";

/** HTTP-facing handlers; routing and auth live in the gateway layer. */
export interface ReserveRequest {
  reservationId: number;
  skuId: number;
  qty: number;
  ttlMs: number;
}

export function handleReserve(
  catalog: Catalog,
  reservations: Reservations,
  req: ReserveRequest,
  now: number,
): { ok: true } | { ok: false; error: string } {
  if (!catalog.has(req.skuId)) return { ok: false, error: "unknown sku" };
  if (req.qty <= 0) return { ok: false, error: "qty must be positive" };
  const r: Reservation = {
    id: req.reservationId,
    skuId: req.skuId,
    qty: req.qty,
    expiresAt: now + req.ttlMs,
  };
  try {
    reservations.reserve(r);
  } catch (err) {
    return { ok: false, error: (err as Error).message };
  }
  return { ok: true };
}

export function handleRenew(
  reservations: Reservations,
  reservationId: number,
  now: number,
  ttlMs: number,
): { ok: true } {
  // Called by the storefront keep-alive every 5 minutes per active buyer.
  reservations.touch(reservationId, now, ttlMs);
  return { ok: true };
}

export function handleRecentPanel(reservations: Reservations, limit: number): number[] {
  return reservations.recent(limit);
}

