import { describe, expect, it } from "vitest";
import { Catalog } from "./catalog.js";
import { Reservations } from "./reservations.js";

/** Test ids come from a local counter for readability. */
let nextId = 1;
function makeReservation(skuId: number, qty: number, expiresAt: number) {
  return { id: nextId++, skuId, qty, expiresAt };
}

function catalogWith(...skus: Array<[number, string, number]>): Catalog {
  const c = new Catalog();
  for (const [id, name, stock] of skus) c.add({ id, name, stock });
  return c;
}

describe("Reservations", () => {
  it("reserves and confirms, adjusting stock once", () => {
    const c = catalogWith([10, "crate", 5]);
    const r = new Reservations(c);
    const a = makeReservation(10, 2, 1000);
    r.reserve(a);
    expect(c.get(10)?.stock).toBe(3);
    r.confirm(a.id);
    expect(r.active()).toBe(0);
    expect(r.panelConsistent()).toBe(true);
  });

  it("releases expired reservations back to stock", () => {
    const c = catalogWith([10, "crate", 5], [11, "pallet", 4]);
    const r = new Reservations(c);
    r.reserve(makeReservation(10, 2, 1000));
    r.reserve(makeReservation(11, 1, 1000));
    r.reserve(makeReservation(10, 1, 5000));
    expect(r.releaseExpired(2000)).toBe(2);
    expect(c.get(10)?.stock).toBe(4);
    expect(c.get(11)?.stock).toBe(4);
    expect(r.active()).toBe(1);
    expect(r.panelConsistent()).toBe(true);
  });

  it("keeps the recent panel in recency order", () => {
    const c = catalogWith([10, "crate", 50]);
    const r = new Reservations(c);
    const ids = [makeReservation(10, 1, 9000), makeReservation(10, 1, 9000), makeReservation(10, 1, 9000)];
    for (const x of ids) r.reserve(x);
    expect(r.recent(2)).toEqual([ids[1].id, ids[2].id]);
  });

  it("confirm removes the reservation from the panel", () => {
    const c = catalogWith([10, "crate", 50]);
    const r = new Reservations(c);
    const a = makeReservation(10, 1, 9000);
    const b = makeReservation(10, 1, 9000);
    r.reserve(a);
    r.reserve(b);
    r.confirm(a.id);
    expect(r.recent(10)).toEqual([b.id]);
    expect(r.panelConsistent()).toBe(true);
  });
});

--- excerpt: docs/warehouse-ops.md (for reviewer context) ---
The warehouse service runs one node per site. Reservations are held for 15
minutes (checkout TTL) and renewed by the storefront every 5 minutes while
the buyer is active — a busy buyer's reservation is touched two or three
times before confirm. At the Osaka and Reno sites we see 300-900 active
reservations at peak and the sweeper runs every 30 seconds. Since the id
service moved to interleaved block allocation in June, ops has an open,
unreproduced ticket (WH-2214) about the dashboard's recent-activity panel
occasionally showing "ghost" reservations that were already released, and
about weekly stock counts drifting upward at the two busiest sites — both
filed as cosmetic pending investigation. Support has separately reported
two oversell incidents this month that inventory later attributed to
"phantom stock returns"; those tickets (SUP-8817, SUP-8902) are still open
with no root cause. The team suspects a race in the storefront and has been
unable to reproduce any of this in staging, where load tests run against a
single-node id allocator.

Operationally, stock correctness is the one thing this service exists to
guarantee: the storefront trusts adjustStock as the single source of truth,
and a reservation that is neither confirmed, cancelled, nor released is
stock that silently never returns to sale. The dashboard's recent-activity
panel is cosmetic, but the PANEL_DRIFT probe shipping in this release was
added specifically so that WH-2214 stops being unfalsifiable — if the panel
and the live set disagree, we want an alert, not a screenshot in a ticket.
Reviewers should assume peak-load conditions at Osaka: interleaved ids
arriving out of order, buyers renewing reservations mid-checkout, and the
sweeper firing every 30 seconds while all of that is in flight.

History for context: the slots.ts binary-search utilities predate this
service — they were extracted from the catalog code two years ago precisely
because the catalog is careful to keep its id arrays sorted through
insertSorted. The reservations module arrived last year in a different team
and was merged into this repo during the January reorg; this is the first
release where the same reviewer sees both sides. The load tests in staging
exercise reserve/confirm at volume but drive renewals through a stubbed
keep-alive that fires exactly once per reservation, immediately after
creation, which the load-test authors considered equivalent to production
behavior.

Release process note: this review is the last gate. There is no canary for
warehouse nodes — sites run one node each, so the release goes to Reno first
on Friday night and to the remaining sites on Monday. If a stock-accounting
defect ships, the earliest signal is the weekly inventory reconciliation the
following Thursday, which is why reviewers are asked to reason about
correctness from the code rather than lean on post-deploy monitoring. The
previous release shipped the sweeper unchanged for six months, so any new
symptom pattern that started in June points at data shape, not code churn.

This is Friday's release candidate for the warehouse service. QA signed off
and the unit tests above are green in CI. Before we ship, review all four
files together. At least one production bug spans more than one file — a
contract declared in one file broken by a caller in another. Your review must:

1. Identify the cross-file bug precisely: the contract, the function that
   declares it, the call sites that violate it, and the exact sequence of
   production events that makes the violation bite (be specific about what
   `touch` does to the ordering, and about where production ids come from
   per the catalog.ts comment).
2. Explain the user-visible consequence for stock accounting and for the
   dashboard invariant, and connect it to the open ops tickets in the
   warehouse-ops excerpt (which reported symptoms does this bug explain, and
   why does it not reproduce in staging?).
3. Explain concretely why the test suite stays green despite the bug — what
   is special about how the tests construct their data.
4. Give the minimal fix, and say which of the two plausible fixes you would
   ship and why.
5. Note anything else worth flagging in these files, briefly — real issues
   only, not style nits; say explicitly if a flagged item is speculative.

