import { httpGet } from "../lib/http.js";
import { userCache } from "./userCache.js";
import type { UserRecord } from "./types.js";

export async function fetchUser(userId: string): Promise<UserRecord> {
  const cached = userCache.get(userId);
  if (cached !== undefined) return cached;
  const record = await httpGet<UserRecord>("/internal/users/" + userId);
  userCache.set(userId, record);
  return record;
}

export async function fetchUserOrNull(userId: string): Promise<UserRecord | null> {
  try {
    return await fetchUser(userId);
  } catch (err) {
    if ((err as { status?: number }).status === 404) return null;
    throw err;
  }
}

