import { fetchUser, fetchUserOrNull } from "../api/fetchUser.js";
import { userCache } from "../api/userCache.js";
import type { UserRecord } from "../api/types.js";

export async function renderProfile(userId: string): Promise<string> {
  const record: UserRecord = await fetchUser(userId);
  return "<h1>" + record.displayName + "</h1><p>" + record.plan + "</p>";
}

export async function renderProfileSafe(userId: string): Promise<string> {
  const record = await fetchUserOrNull(userId);
  if (record === null) return "<p>No such user (" + userId + ")</p>";
  return renderProfile(record.userId);
}

export function onUserUpdated(userId: string): void {
  userCache.invalidate(userId);
}

We are renaming the user-facing "user" concept to "account" in the API layer.
Apply EXACTLY this rename across all four files:

- fetchUser -> loadAccount, fetchUserOrNull -> loadAccountOrNull
- UserRecord -> AccountRecord, UserPage -> AccountPage
- userCache -> accountCache, UserCacheImpl -> AccountCacheImpl

Everything else stays byte-for-byte identical — including the `userId`
parameter and field (it is NOT being renamed), string literals, URLs, and the
file names in the headers except that src/api/fetchUser.ts becomes
src/api/loadAccount.ts and src/api/userCache.ts becomes
src/api/accountCache.ts (update the import paths that reference them).

Output only the four updated files in full, each preceded by its
